create or replace function private.workflow_health_monitor() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not (public.has_permission_for_current_user('view_jobs') or public.has_permission_for_current_user('view_billing') or public.has_permission_for_current_user('view_dispatch')) then raise exception 'Workflow permission required'; end if; return jsonb_build_object('bookedUnscheduled',(select count(*) from public.jobs where status='booked' and scheduled_start is null and created_at<now()-interval '2 hours'),'scheduledUnassigned',(select count(*) from public.jobs where status in ('scheduled','dispatched') and technician_id is null and scheduled_start is not null and scheduled_start<now()+interval '24 hours'),'onSiteStale',(select count(*) from public.jobs where status='on_site' and updated_at<now()-interval '6 hours'),'completedUninvoiced',(select count(*) from public.jobs j where j.status='completed' and not exists(select 1 from public.invoices i where i.job_id=j.id)),'openInvoiceUnpaid',(select count(*) from public.invoices i where i.status='open' and i.created_at<now()-interval '1 day'),'paidNotClosed',(select count(*) from public.jobs j where j.status='completed' and exists(select 1 from public.invoices i where i.job_id=j.id) and not exists(select 1 from public.invoices i where i.job_id=j.id and i.status<>'paid')),'retentionDue',(select count(*) from public.post_job_followups where status='pending' and due_at<=now())); end $$; create or replace function public.workflow_health_monitor() returns jsonb language sql stable set search_path='' as $$ select private.workflow_health_monitor() $$; revoke all on function public.workflow_health_monitor() from public,anon; grant execute on function public.workflow_health_monitor() to authenticated;